package unifi_test

import (
	"testing"

	"github.com/mattoddie/unifi-mcp/internal/ojson"
	"github.com/mattoddie/unifi-mcp/internal/unifi"
)

func jsonOf(v any) string {
	s, _ := ojson.Stringify(v)
	return s
}

func TestRedactSecrets(t *testing.T) {
	out := unifi.RedactSecrets(ojson.MustParse(`{
		"key":"mgmt","name":"Office","zone_key":"internal","community":"public-ro","x_passphrase":"hunter22",
		"passphrase_autogenerated":true,"radius_secret":"s3","secret":"s4","private_key":"wg-private","privatekey":"wg-private-2",
		"api_key":"abc","auth_token":"tok","configuration_file":"client\nremote vpn.example","openvpn_config_file":"x",
		"ssh_authorized_tokens":["a","b"],"private_preshared_keys":[{"networkconf_id":"n1","password":"ppsk-1"}],
		"nested":{"pppoe":{"username":"isp","password":"pw"},"psk":"abc"},"empty_password":"","x_count":5}`))
	want := `{"key":"mgmt","name":"Office","zone_key":"internal","community":"[redacted]","x_passphrase":"[redacted]",` +
		`"passphrase_autogenerated":true,"radius_secret":"[redacted]","secret":"[redacted]","private_key":"[redacted]","privatekey":"[redacted]",` +
		`"api_key":"[redacted]","auth_token":"[redacted]","configuration_file":"[redacted]","openvpn_config_file":"[redacted]",` +
		`"ssh_authorized_tokens":["[redacted]","[redacted]"],"private_preshared_keys":[{"networkconf_id":"n1","password":"[redacted]"}],` +
		`"nested":{"pppoe":{"username":"isp","password":"[redacted]"},"psk":"[redacted]"},"empty_password":"","x_count":5}`
	if got := jsonOf(out); got != want {
		t.Errorf("redaction:\n got  %s\n want %s", got, want)
	}
	if got := jsonOf(unifi.RedactSecrets(ojson.MustParse(`[{"x_a":"b"},"plain",3]`))); got != `[{"x_a":"[redacted]"},"plain",3]` {
		t.Errorf("array: %s", got)
	}
}

func TestNormalizeMac(t *testing.T) {
	for in, want := range map[string]string{"AA-BB-CC-DD-EE-FF": "aa:bb:cc:dd:ee:ff", "aabb.ccdd.eeff": "aa:bb:cc:dd:ee:ff", "AABBCCDDEEFF": "aa:bb:cc:dd:ee:ff"} {
		if got, err := unifi.NormalizeMac(in); err != nil || got != want {
			t.Errorf("%s: %s %v", in, got, err)
		}
	}
	if _, err := unifi.NormalizeMac("aa:bb"); err == nil || err.Error() != "Invalid MAC address: aa:bb" {
		t.Errorf("short: %v", err)
	}
}

func TestTimesAndDurations(t *testing.T) {
	for in, want := range map[float64]any{1700000000: "2023-11-14T22:13:20.000Z", 1700000000123: "2023-11-14T22:13:20.123Z", 0: ojson.Undefined, -5: ojson.Undefined} {
		if got := unifi.IsoTime(in); got != want {
			t.Errorf("isoTime(%v) = %v", in, got)
		}
	}
	if unifi.IsoTime("1700000000") != ojson.Undefined {
		t.Error("strings are not times")
	}
	for in, want := range map[float64]string{90061: "1d 1h 1m", 3600: "1h 0m", 59: "0m", 7260.5: "2h 1m"} {
		if got := unifi.Duration(in); got != want {
			t.Errorf("duration(%v) = %v", in, got)
		}
	}
	if unifi.Duration(-1.0) != ojson.Undefined {
		t.Error("negative duration")
	}
}

func TestSummaries(t *testing.T) {
	c := unifi.SummarizeClient(ojson.MustParse(`{"_id":"u","mac":"m","is_wired":null,"tx_rate":866050,"rx_rate":1250,"is_guest":true,"authorized":false,"use_fixedip":true,"fixed_ip":"1.2.3.4","last_ip":"5.6.7.8","signal":-60}`).(*ojson.Obj))
	if got := jsonOf(c); got != `{"id":"u","mac":"m","ip":"5.6.7.8","fixed_ip":"1.2.3.4","connection":"wireless","signal_dbm":-60,"tx_rate_mbps":866.1,"rx_rate_mbps":1.3,"guest":true,"authorized":false}` {
		t.Errorf("client: %s", got)
	}
	d := unifi.SummarizeDevice(ojson.MustParse(`{"_id":"d","type":"udm","state":5,"upgradable":true,"upgrade_to_firmware":"9","system-stats":{"cpu":"x"},"uplink":{"type":"wire","uplink_mac":"aa","speed":1000},"last_seen":1700000000}`).(*ojson.Obj))
	if got := jsonOf(d); got != `{"id":"d","type":"gateway_console","state":"provisioning","upgradable":true,"upgrade_to_firmware":"9","cpu_pct":null,"uplink":{"type":"wire","device_mac":"aa","speed_mbps":1000},"last_seen":"2023-11-14T22:13:20.000Z"}` {
		t.Errorf("device: %s", got)
	}
	p := unifi.SummarizePort(ojson.MustParse(`{"port_idx":1,"up":false,"speed":1000,"poe_power":"2.5","rx_errors":1,"tx_errors":2}`).(*ojson.Obj))
	if got := jsonOf(p); got != `{"idx":1,"up":false,"poe_power_w":2.5,"errors":3}` {
		t.Errorf("port: %s", got)
	}
	n := unifi.SummarizeNetwork(ojson.MustParse(`{"_id":"n","purpose":"wan","wan_type":"dhcp","dhcpd_enabled":true,"dhcpd_start":"a","vlan":0}`).(*ojson.Obj))
	if got := jsonOf(n); got != `{"id":"n","purpose":"wan","dhcp_enabled":true,"dhcp_range":"a-undefined","wan_type":"dhcp"}` {
		t.Errorf("network: %s", got)
	}
}
